bat_d = 13;    // depth (Y) - thickness, batteries face each other along Y
bat_h = 56;    // height (Z) - standing upright

// Tolerances and wall parameters
tol = 0.5;        // tolerance around battery
wall = 2.5;       // wall thickness
floor_t = 2.5;    // floor thickness
divider_t = 2.0;  // divider thickness between batteries

// Slot internal dimensions (with tolerance)
slot_w = bat_w + 2*tol;  // 37mm
slot_d = bat_d + 2*tol;  // 14mm
slot_h = bat_h + 1;      // 57mm (battery sticks up slightly for easy grab)

// Snap-fit parameters
snap_width = 10;      // width of snap tab
snap_depth = 1.2;     // how far snap protrudes into slot
snap_height = 3;      // height of snap bump
snap_z = slot_h - 12; // position from bottom (near top of battery)
snap_ramp = 2;        // ramp length above snap for insertion

