case_d = n_bat * slot_d + (n_bat - 1) * divider_t + 2*wall;  // 4 slots + 3 dividers + 2 walls
case_h = slot_h + floor_t; // total height

// Corner radius
corner_r = 3;

echo("Case dimensions:", case_w, case_d, case_h);

module rounded_box(w, d, h, r) {
    translate([r, r, 0])
    minkowski() {
        cube([w - 2*r, d - 2*r, h/2]);
        cylinder(r=r, h=h/2, $fn=32);
    }
}

module snap_tab(height_pos) {
    // A snap-fit bump that protrudes into the slot
    // Shaped like a ramp on top and a ledge on bottom for retention
    hull() {
        translate([0, 0, height_pos])
            cube([snap_width, 0.1, snap_height]);
        translate([0, snap_depth, height_pos + snap_height*0.3])
            cube([snap_width, 0.1, snap_height*0.4]);
    }
    // Ramp on top for easy insertion
    hull() {
        translate([0, snap_depth, height_pos + snap_height*0.7])
            cube([snap_width, 0.1, snap_height*0.3]);
        translate([0, 0.1, height_pos + snap_height])
            cube([snap_width, 0.1, snap_ramp]);
    }
}

