            snap_tab(snap_z - floor_t);

        // Back wall of slot (upper Y side, mirrored)
        translate([slot_x_center + snap_width/2, slot_y + slot_d, floor_t])
            rotate([0, 0, 180])
                snap_tab(snap_z - floor_t);
    }
}

// Add subtle grip texture / label area on outside
module final_case() {
    difference() {
        battery_case();

        // Add grip grooves on the long sides for aesthetics/grip
        for (i = [0:7]) {
