// ===== Parameters =====
// Battery dimensions
bat_w = 36;    // width (X)
bat_d = 13;    // depth (Y) - batteries line up along Y
bat_h = 56;    // height (Z) - standing upright

// Tolerances and structure
tol = 0.5;          // clearance around battery
wall = 2.5;         // outer wall thickness
floor_t = 3.0;      // floor thickness
divider_t = 2.0;    // wall between adjacent batteries

// Slot internal dimensions
slot_w = bat_w + 2*tol;   // 37mm
slot_d = bat_d + 2*tol;   // 14mm  
slot_h = bat_h - 3;       // 53mm - battery protrudes 3mm above for easy grip

// Number of batteries
n_bat = 4;

// Snap-fit parameters
snap_w = 8;           // width of each snap tab
snap_protrude = 1.0;  // how far it sticks into slot
snap_bump_h = 2.5;    // height of the snap bump
snap_z = slot_h - 8;  // Z position of snap (near top)
snap_flex_h = 15;     // height of flex cantilever behind snap
snap_flex_gap = 0.8;  // gap behind cantilever for flex

// Finger hole parameters
finger_d = 16;        // finger hole diameter through floor

// Corner radius
corner_r = 3;

// Derived overall dimensions
case_w = slot_w + 2*wall;
case_d = n_bat * slot_d + (n_bat-1) * divider_t + 2*wall;
case_h = slot_h + floor_t;

$fn = 48;

echo(str("Case size: ", case_w, " x ", case_d, " x ", case_h, " mm"));

// ===== Modules =====

// Rounded rectangle extrusion
module rounded_rect(w, d, h, r) {
    linear_extrude(height=h)
        offset(r=r)
            offset(r=-r)
                square([w, d]);
}

// Snap-fit cantilever tab - prints pointing upward
// Origin at base of cantilever on the wall surface
// Protrudes in +Y direction
module snap_cantilever() {
    // Thin cantilever beam
    cant_thick = 1.2;

    // The cantilever arm (vertical beam with snap bump at top)
    // Base attached to wall, free end has the bump
    union() {
        // Bump/catch - the part that holds the battery
        // Ramped on top for insertion, sharp ledge on bottom for retention
        translate([0, 0, snap_z]) {
            // Sharp retaining ledge (bottom face)
            // Ramp shape for easy insertion from top
            hull() {
                // Base of bump at wall
                translate([0, 0, 0])
                    cube([snap_w, 0.2, snap_bump_h]);
                // Tip of bump protruding into slot
                translate([0, snap_protrude, snap_bump_h * 0.4])
                    cube([snap_w, 0.2, snap_bump_h * 0.2]);
            }
            // Upper ramp for insertion
            hull() {
                translate([0, snap_protrude, snap_bump_h * 0.6])
                    cube([snap_w, 0.2, snap_bump_h * 0.1]);
                translate([0, 0.2, snap_bump_h])
                    cube([snap_w, 0.2, 3]);
            }
        }
    }
}

module battery_case() {
    difference() {
        // === OUTER SHELL ===
        rounded_rect(case_w, case_d, case_h, corner_r);

        // === CUT BATTERY SLOTS ===
        for (i = [0:n_bat-1]) {
            sy = wall + i * (slot_d + divider_t);

            // Main slot
            translate([wall, sy, floor_t])
                cube([slot_w, slot_d, slot_h + 10]);

            // Top chamfer/bevel for easy battery insertion
            translate([wall - 1, sy - 1, case_h - 3])
                linear_extrude(height=3.5, scale=[(slot_w+4)/slot_w, (slot_d+4)/slot_d])
                    translate([-(2)/(2*(slot_w+4)/slot_w -1)*0 , 0, 0])
                        square([slot_w, slot_d]);

            // Finger access hole through floor
            translate([wall + slot_w/2, sy + slot_d/2, -1])
                cylinder(d=finger_d, h=floor_t + 2);

            // Finger hole countersink on bottom for nicer feel
            translate([wall + slot_w/2, sy + slot_d/2, -1])
                cylinder(d1=finger_d + 4, d2=finger_d, h=2);
        }

        // === CHAMFER TOP EDGES of outer shell ===
        difference() {
            translate([-1, -1, case_h - 1.5])
                cube([case_w + 2, case_d + 2, 2]);
            translate([0, 0, case_h - 1.5])
                rounded_rect(case_w, case_d, 2, corner_r);
        }
    }

    // === SNAP-FIT TABS ===
    // Add snap tabs on the two long walls (X-direction walls) of each slot
    for (i = [0:n_bat-1]) {
        sy = wall + i * (slot_d + divider_t);
        cx = wall + slot_w/2;

        // Left side snap (on the wall at X = wall, protruding in +X)
        translate([wall, sy + slot_d/2 - snap_w/2, floor_t])
            snap_cantilever();

        // Right side snap (on the wall at X = wall+slot_w, protruding in -X)
        translate([wall + slot_w, sy + slot_d/2 + snap_w/2, floor_t])
            rotate([0, 0, 180])
                snap_cantilever();
    }

    // Snap tabs on the front/back of each slot (Y walls)
    for (i = [0:n_bat-1]) {
        sy = wall + i * (slot_d + divider_t);
        cx = wall + slot_w/2;

        // Near-side Y wall snap
        translate([cx - snap_w/2, sy, floor_t])
            snap_cantilever();

        // Far-side Y wall snap  
        translate([cx + snap_w/2, sy + slot_d, floor_t])
            rotate([0, 0, 180])
                snap_cantilever();
    }
}

// ===== Label / visual details =====
module final_case() {
    difference() {
        battery_case();

        // Engraved text on front
        translate([case_w/2, -0.1, case_h/2])
            rotate([90, 0, 0])
                linear_extrude(height=1)
                    text("BLS-5", size=7, halign="center", valign="center", font="Liberation Sans:style=Bold");

        // Battery number labels near each slot on front
        for (i = [0:n_bat-1]) {
            sy = wall + i * (slot_d + divider_t) + slot_d/2;
            translate([case_w/2, -0.1, case_h - 8])
                rotate([90, 0, 0])
                    linear_extrude(height=0.8) {
                        // small tick mark
                    }
        }
    }
}

final_case();
