{'content': '// Olympus BLS-5 Battery Case - Holds 4 batteries in 4x1 linear arrangement
// Battery: 56 x 36 x 13 mm
// Standing upright on 13x36mm face, largest faces (56x36) facing each other
// Printable in one piece, snap-fit retention, finger holes for removal

// ===== Parameters =====
bat_w = 36;    // battery width (X direction)
bat_d = 13;    // battery depth (Y direction) - line up along Y
bat_h = 56;    // battery height (Z direction) - standing up

tol = 0.5;          // clearance per side
wall = 2.5;         // outer wall thickness  
floor_t = 3.0;      // floor thickness
divider_t = 2.0;    // divider between slots

slot_w = bat_w + 2*tol;   // 37
slot_d = bat_d + 2*tol;   // 14
expose = 8;                // how much battery sticks above case for grip
slot_h = bat_h - expose;   // 48mm internal height

n_bat = 4;

// Snap-fit
snap_w = 8;
snap_protrude = 1.0;
snap_bump_h = 2.5;
snap_z_from_top = 6;  // distance from top of slot wall

// Finger hole
finger_d = 16;

// Corner radius
corner_r = 3;

// Overall case
case_w = slot_w + 2*wall;     // 42
case_d = n_bat*slot_d + (n_bat-1)*divider_t + 2*wall;  // 4*14 + 3*2 + 5 = 67
case_h = slot_h + floor_t;    // 51

$fn = 48;

echo(str("Case: ", case_w, " x ", case_d, " x ", case_h, " mm"));

// ===== Modules =====

module rcube(size, r) {
    // Rounded cube with radius on vertical edges
    hull() {
        for (x = [r, size[0]-r])
            for (y = [r, size[1]-r])
                translate([x, y, 0])
                    cylinder(r=r, h=size[2]);
    }
}

// Snap bump: sits on wall, protrudes into slot
// Origin at wall surface, extends in +Y, centered in X on snap_w
module snap_bump() {
    sz = snap_z_from_top;
    z_pos = slot_h - sz - snap_bump_h;

    translate([0, 0, z_pos]) {
        // Lower retention shelf - steeper angle for positive lock
        hull() {
            cube([snap_w, 0.01, snap_bump_h*0.35]);
            translate([0, snap_protrude, snap_bump_h*0.35])
                cube([snap_w, 0.01, 0.01]);
        }
        // Upper ramp for easy push-in insertion
        hull() {
            translate([0, snap_protrude, snap_bump_h*0.35])
                cube([snap_w, 0.01, 0.01]);
            translate([0, 0.01, snap_bump_h])
                cube([snap_w, 0.01, 0.01]);
        }
        // Smooth transition above bump
        hull() {
            translate([0, 0.01, snap_bump_h])
                cube([snap_w, 0.01, 0.01]);
            translate([0, 0, snap_bump_h + 2])
                cube([snap_w, 0.01, 0.01]);
        }
    }
}

// Slot Y position
function slot_y(i) = wall + i * (slot_d + divider_t);

module case_body() {
    difference() {
        // Outer shell
        rcube([case_w, case_d, case_h], corner_r);

        for (i = [0:n_bat-1]) {
            sy = slot_y(i);

            // Battery slot cavity
            translate([wall, sy, floor_t])
                cube([slot_w, slot_d, slot_h + 1]);

            // Top insertion chamfer - flare out the top 3mm
            translate([wall, sy, 0])
            hull() {
                // At case_h - 3, match slot size
                translate([0, 0, case_h - 3])
                    cube([slot_w, slot_d, 0.01]);
                // At case_h, slightly wider
                translate([-1.5, -1, case_h])
                    cube([slot_w + 3, slot_d + 2, 0.01]);
            }

            // Finger hole through floor
            translate([wall + slot_w/2, sy + slot_d/2, -1])
                cylinder(d=finger_d, h=floor_t + 2);

            // Chamfer finger hole on bottom surface for comfort
            translate([wall + slot_w/2, sy + slot_d/2, 0])
                rotate([180, 0, 0])
                    cylinder(d1=finger_d, d2=finger_d+3, h=1.5);
        }

        // Outer top edge chamfer (cosmetic)
        translate([0, 0, case_h])
        difference() {
            translate([-1, -1, -2])
                cube([case_w+2, case_d+2, 2.5]);
            // Keep the inner rounded shape
            translate([0, 0, -2])
                rcube([case_w, case_d, 2.5], corner_r - 0.5);
            // Chamfer
            hull() {
                translate([0, 0, -2])
                    rcube([case_w, case_d, 0.01], corner_r);
                translate([0, 0, 0])
                    rcube([case_w-1.5, case_d-1.5, 0.01], corner_r);
            }
        }
    }
}

module snap_tabs() {
    for (i = [0:n_bat-1]) {
        sy = slot_y(i);

        // Snaps on X walls (left and right of each slot)
        // Left wall (+X direction)
        translate([wall, sy + (slot_d - snap_w)/2, floor_t])
            snap_bump();

        // Right wall (-X direction, mirrored)
        translate([wall + slot_w, sy + (slot_d + snap_w)/2, floor_t])
            rotate([0, 0, 180])
                snap_bump();
    }
}

module divider_relief() {
    // Add slight relief cuts in dividers so they can flex slightly
    // This helps snap-fit work better with the Y-direction snaps
    for (i = [0:n_bat-2]) {
        dy = wall + (i+1)*slot_d + i*divider_t + divider_t/2;
        // Relief slot in center of divider
        translate([wall + slot_w*0.2, dy - 0.3, floor_t + slot_h*0.5])
            cube([slot_w*0.6, 0.6, slot_h*0.5 + 1]);
    }
}

module engraved_text() {
    // "BLS-5" on front face
    translate([case_w/2, 0.5, case_h*0.4])
        rotate([90, 0, 0])
            linear_extrude(height=1)
                text("BLS-5", size=6, halign="center", valign="center",
                     font="Liberation Sans:style=Bold");

    // "×4" 
    translate([case_w/2, 0.5, case_h*0.4 - 10])
        rotate([90, 0, 0])
            linear_extrude(height=1)
                text("×4", size=5, halign="center", valign="center",
                     font="Liberation Sans");

    // Slot numbers on front edge
    for (i = [0:n_bat-1]) {
        sy = slot_y(i) + slot_d/2;
        translate([0.5, sy, case_h - 1])
            rotate([0, -90, 0])
                rotate([0, 0, 90])
                    linear_extrude(height=0.8)
                        text(str(i+1), size=4, halign="center", valign="center",
                             font="Liberation Sans");
    }
}

// ===== Assembly =====
module final_case() {
    difference() {
        union() {
            case_body();
            snap_tabs();
        }
        engraved_text();
        //divider_relief();  // optional
    }
}

final_case();
'}

{'content': '// Olympus BLS-5 Battery Case - 4x1 Linear Arrangement
// Battery: 56 x 36 x 13 mm
// Upright on 13x36mm face, largest faces (56x36) facing each other
// One-piece 3D printable, snap-fit retention, finger holes for removal

// ===== Parameters =====
bat_w = 36;    // width (X)
bat_d = 13;    // depth (Y) - batteries lined up along Y
bat_h = 56;    // height (Z) - standing upright

tol = 0.5;
wall = 2.5;
floor_t = 3.0;
divider_t = 2.0;

slot_w = bat_w + 2*tol;     // 37
slot_d = bat_d + 2*tol;     // 14
expose = 10;                 // battery protrudes above case
slot_h = bat_h - expose;    // 46mm internal

n_bat = 4;

// Snap-fit
snap_w = 10;
snap_protrude = 1.0;
snap_bump_h = 2.5;
snap_from_top = 4;  // how far below top of wall the snap sits

// Finger hole
finger_d = 16;

corner_r = 3;

// Overall
case_w = slot_w + 2*wall;
case_d = n_bat*slot_d + (n_bat-1)*divider_t + 2*wall;
case_h = slot_h + floor_t;

$fn = 48;

echo(str("Case: ", case_w, "x", case_d, "x", case_h, " mm"));

// ===== Helpers =====
module rcube(size, r) {
    hull() {
        for (x=[r, size[0]-r], y=[r, size[1]-r])
            translate([x, y, 0])
                cylinder(r=r, h=size[2]);
    }
}

function slot_y(i) = wall + i*(slot_d + divider_t);

// Snap bump on wall surface, protrudes in +Y
module snap_bump(z_base) {
    z = z_base;
    // Retention ledge (sharper bottom face)
    hull() {
        translate([0, 0, z])
            cube([snap_w, 0.01, snap_bump_h*0.3]);
        translate([0, snap_protrude, z + snap_bump_h*0.3])
            cube([snap_w, 0.01, 0.01]);
    }
    // Ramp (gentler top face for push-in)
    hull() {
        translate([0, snap_protrude, z + snap_bump_h*0.3])
            cube([snap_w, 0.01, 0.01]);
        translate([0, 0.01, z + snap_bump_h])
            cube([snap_w, 0.01, 0.01]);
    }
    // Blend back to wall above
    hull() {
        translate([0, 0.01, z + snap_bump_h])
            cube([snap_w, 0.01, 0.01]);
        translate([0, 0, z + snap_bump_h + 2])
            cube([snap_w, 0.01, 0.01]);
    }
}

// ===== Main Case =====
module battery_case() {
    snap_z = slot_h - snap_from_top - snap_bump_h;

    difference() {
        union() {
            // --- Outer shell ---
            rcube([case_w, case_d, case_h], corner_r);

            // --- Snap tabs on X walls (left/right of each slot) ---
            for (i = [0:n_bat-1]) {
                sy = slot_y(i);
                // Left wall snaps (wall face at x=wall, protrude into +X)
                translate([wall, sy + (slot_d-snap_w)/2, floor_t])
                    snap_bump(snap_z);
                // Right wall snaps (wall face at x=wall+slot_w, protrude into -X)
                translate([wall+slot_w, sy + (slot_d+snap_w)/2, floor_t])
                    rotate([0,0,180])
                        snap_bump(snap_z);
            }
        }

        // --- Slot cavities ---
        for (i = [0:n_bat-1]) {
            sy = slot_y(i);

            // Main cavity
            translate([wall, sy, floor_t])
                cube([slot_w, slot_d, slot_h + 10]);

            // Top entry chamfer - gentle flare for easy insertion
            hull() {
                translate([wall, sy, case_h - 2.5])
                    cube([slot_w, slot_d, 0.01]);
                translate([wall-1.2, sy-0.8, case_h + 0.01])
                    cube([slot_w+2.4, slot_d+1.6, 0.01]);
            }

            // Finger hole through floor
            translate([wall + slot_w/2, sy + slot_d/2, -1])
                cylinder(d=finger_d, h=floor_t + 2);

            // Finger hole chamfer on bottom for comfort
            translate([wall + slot_w/2, sy + slot_d/2, -0.01])
                mirror([0,0,1])
                    cylinder(d1=finger_d, d2=finger_d+4, h=1.5);
        }

        // --- Top outer edge chamfer ---
        difference() {
            translate([-1, -1, case_h - 1.2])
                cube([case_w+2, case_d+2, 1.7]);
            // Inner volume to keep
            hull() {
                translate([0, 0, case_h - 1.2])
                    rcube([case_w, case_d, 0.01], corner_r);
                translate([0.8, 0.8, case_h + 0.01])
                    rcube([case_w-1.6, case_d-1.6, 0.01], max(corner_r-0.8, 0.5));
            }
        }

        // --- Engraved text ---
        // "BLS-5" on front
        translate([case_w/2, -0.01, case_h*0.45])
            rotate([90, 0, 0])
                mirror([1,0,0])
                    linear_extrude(height=0.8)
                        text("BLS-5", size=7, halign="center", valign="center",
                             font="Liberation Sans:style=Bold");

        // "×4" below
        translate([case_w/2, -0.01, case_h*0.45 - 11])
            rotate([90, 0, 0])
                mirror([1,0,0])
                    linear_extrude(height=0.8)
                        text("×4", size=5.5, halign="center", valign="center",
                             font="Liberation Sans");

        // Decorative grip lines on both short ends
        for (side = [0, 1]) {
            for (j = [0:5]) {
                z = floor_t + 8 + j*5;
                if (side == 0) {
                    translate([-0.01, wall + 3 + j*0, z])
                        rotate([0, 90, 0])
                            cylinder(d=1.2, h=0.8, $fn=16);
                }
            }
        }
    }
}

// ===== Grip ribs on bottom =====
module bottom_ribs() {
    rib_h = 0.8;
    rib_w = 1.2;
    // Cross ribs on bottom for grip on table
    for (x = [5 : 6 : case_w-3]) {
        translate([x, corner_r, -rib_h])
            cube([rib_w, case_d - 2*corner_r, rib_h]);
    }
}

// ===== Final Assembly =====
module final_case() {
    union() {
        battery_case();
        bottom_ribs();
    }
}

final_case();
'}

{'content': '// Olympus BLS-5 Battery Case - 4x1 Linear Arrangement
// Battery: 56 x 36 x 13 mm
// Upright on 13x36mm face, largest faces (56x36) facing each other
// One-piece 3D printable, snap-fit retention, finger holes for removal

// ===== Parameters =====
bat_w = 36;    // width (X)
bat_d = 13;    // depth (Y) - batteries lined up along Y
bat_h = 56;    // height (Z) - standing upright

tol = 0.5;
wall = 2.5;
floor_t = 3.0;
divider_t = 2.0;

slot_w = bat_w + 2*tol;     // 37
slot_d = bat_d + 2*tol;     // 14
expose = 10;                 // battery protrudes above case for grip
slot_h = bat_h - expose;    // 46mm internal height

n_bat = 4;

// Snap-fit
snap_w = 10;
snap_protrude = 1.0;
snap_bump_h = 2.5;
snap_from_top = 4;

// Finger hole
finger_d = 16;

corner_r = 3;

// Overall
case_w = slot_w + 2*wall;
case_d = n_bat*slot_d + (n_bat-1)*divider_t + 2*wall;
case_h = slot_h + floor_t;

$fn = 48;

echo(str("Case: ", case_w, "x", case_d, "x", case_h, " mm"));

// ===== Helpers =====
module rcube(size, r) {
    hull() {
        for (x=[r, size[0]-r], y=[r, size[1]-r])
            translate([x, y, 0])
                cylinder(r=r, h=size[2]);
    }
}

function slot_y(i) = wall + i*(slot_d + divider_t);

// Snap bump on wall surface, protrudes in +Y
module snap_bump(z_base) {
    z = z_base;
    // Retention ledge (sharper bottom face for positive lock)
    hull() {
        translate([0, 0, z])
            cube([snap_w, 0.01, snap_bump_h*0.3]);
        translate([0, snap_protrude, z + snap_bump_h*0.3])
            cube([snap_w, 0.01, 0.01]);
    }
    // Ramp (gentler top face for push-in)
    hull() {
        translate([0, snap_protrude, z + snap_bump_h*0.3])
            cube([snap_w, 0.01, 0.01]);
        translate([0, 0.01, z + snap_bump_h])
            cube([snap_w, 0.01, 0.01]);
    }
    // Blend back to wall above
    hull() {
        translate([0, 0.01, z + snap_bump_h])
            cube([snap_w, 0.01, 0.01]);
        translate([0, 0, z + snap_bump_h + 2])
            cube([snap_w, 0.01, 0.01]);
    }
}

// ===== Main Case =====
module battery_case() {
    snap_z = slot_h - snap_from_top - snap_bump_h;

    difference() {
        union() {
            // --- Outer shell ---
            rcube([case_w, case_d, case_h], corner_r);

            // --- Snap tabs on X walls (left/right of each slot) ---
            for (i = [0:n_bat-1]) {
                sy = slot_y(i);
                // Left wall snaps
                translate([wall, sy + (slot_d-snap_w)/2, floor_t])
                    snap_bump(snap_z);
                // Right wall snaps
                translate([wall+slot_w, sy + (slot_d+snap_w)/2, floor_t])
                    rotate([0,0,180])
                        snap_bump(snap_z);
            }

            // --- Bottom grip ribs ---
            for (x = [5 : 6 : case_w-3]) {
                translate([x, corner_r, -0.8])
                    cube([1.2, case_d - 2*corner_r, 0.8]);
            }
        }

        // --- Slot cavities ---
        for (i = [0:n_bat-1]) {
            sy = slot_y(i);

            // Main cavity
            translate([wall, sy, floor_t])
                cube([slot_w, slot_d, slot_h + 10]);

            // Top entry chamfer for easy battery insertion
            hull() {
                translate([wall, sy, case_h - 2.5])
                    cube([slot_w, slot_d, 0.01]);
                translate([wall-1.2, sy-0.8, case_h + 0.01])
                    cube([slot_w+2.4, slot_d+1.6, 0.01]);
            }

            // Finger hole through floor
            translate([wall + slot_w/2, sy + slot_d/2, -2])
                cylinder(d=finger_d, h=floor_t + 4);

            // Finger hole chamfer on bottom for comfort
            translate([wall + slot_w/2, sy + slot_d/2, -0.01])
                mirror([0,0,1])
                    cylinder(d1=finger_d, d2=finger_d+4, h=1.5);
        }

        // --- Top outer edge chamfer ---
        difference() {
            translate([-1, -1, case_h - 1.2])
                cube([case_w+2, case_d+2, 1.7]);
            hull() {
                translate([0, 0, case_h - 1.2])
                    rcube([case_w, case_d, 0.01], corner_r);
                translate([0.8, 0.8, case_h + 0.01])
                    rcube([case_w-1.6, case_d-1.6, 0.01], max(corner_r-0.8, 0.5));
            }
        }

        // --- Engraved text on front face (Y=0 face) ---
        translate([case_w/2, 0.8, case_h*0.45])
            rotate([90, 0, 0])
                linear_extrude(height=0.8)
                    text("BLS-5", size=7, halign="center", valign="center",
                         font="Liberation Sans:style=Bold");

        translate([case_w/2, 0.8, case_h*0.45 - 11])
            rotate([90, 0, 0])
                linear_extrude(height=0.8)
                    text("×4", size=5.5, halign="center", valign="center",
                         font="Liberation Sans");
    }
}

battery_case();
'}
